TLM.f("Sancti/11-29r",{"officium":"S. Saturnini Martyris","rule":["vide C2a;"],"fallback":"Commune/C2a","from":{"Introitus":"Commune/C2a","Lectio":"Commune/C2a","Graduale":"Commune/C2a","Tractus":"Commune/C2a","Evangelium":"Commune/C2a","Offertorium":"Commune/C2a","Communio":"Commune/C2a"},"sections":{"Introitus":[{"k":"ref","la":"Ps 63:11"},{"k":"text","la":"Lætábitur justus in Dómino, et sperábit in eo: et laudabúntur omnes recti corde. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 63:2"},{"k":"text","la":"Exáudi, Deus, oratiónem meam cum déprecor: a timóre inimíci éripe ánimam meam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Lætábitur justus in Dómino, et sperábit in eo: et laudabúntur omnes recti corde. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Deus, qui nos beáti Saturníni Mártyris tui concédis natalícia pérfrui: ejus nos tríbue méritis adjuvári."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Timótheum"},{"k":"ref","la":"2 Tim 2:8-10; 3:10-12"},{"k":"text","la":"Caríssime: Memor esto, Dóminum Jesum Christum resurrexísse a mórtuis ex sémine David, secúndum Evangélium meum, in quo labóro usque ad víncula, quasi male óperans: sed verbum Dei non est alligátum. Ideo ómnia sustíneo propter eléctos, ut et ipsi salútem consequántur, quæ est in Christo Jesu, cum glória coelésti. Tu autem assecútus es meam doctrínam, institutiónem, propósitum, fidem, longanimitátem, dilectiónem, patiéntiam, persecutiónes, passiónes: quália mihi facta sunt Antiochíæ, Icónii et Lystris: quales persecutiónes sustínui, et ex ómnibus erípuit me Dóminus. Et omnes, qui pie volunt vívere in Christo Jesu, persecutiónem patiéntur."}],"Graduale":[{"k":"ref","la":"Ps 36:24"},{"k":"text","la":"Justus cum cecíderit, non collidétur: quia Dóminus suppónit manum suam."},{"k":"ref","la":"Ps 36:26"},{"k":"text","la":"Tota die miserétur, et cómmodat: et semen ejus in benedictióne erit. Allelúja, allelúja"},{"k":"ref","la":"Joann 8:12"},{"k":"text","la":"Qui séquitur me, non ámbulat in ténebris: sed habébit lumen vitæ ætérnæ. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 36:24"},{"k":"text","la":"Justus cum cecíderit, non collidétur: quia Dóminus suppónit manum suam."},{"k":"ref","la":"Ps 36:26"},{"k":"text","la":"Tota die miserétur, et cómmodat: et semen ejus in benedictióne erit."},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 10:26-32"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Nihil est opértum, quod non revelábitur; et occúltum, quod non sciétur. Quod dico vobis in ténebris, dícite in lúmine: et quod in aure audítis, prædicáte super tecta. Et nolíte timére eos, qui occídunt corpus, ánimam autem non possunt occídere; sed pótius timéte eum, qui potest et ánimam et corpus pérdere in gehénnam. Nonne duo pásseres asse véneunt: et unus ex illis non cadet super terram sine Patre vestro? Vestri autem capílli cápitis omnes numeráti sunt. Nolíte ergo timére: multis passéribus melióres estis vos. Omnis ergo, qui confitébitur me coram homínibus, confitébor et ego eum coram Patre meo, qui in coelis est."}],"Offertorium":[{"k":"ref","la":"Ps 20:4-5"},{"k":"text","la":"Posuísti, Dómine, in cápite ejus corónam de lápide pretióso: vitam pétiit a te, et tribuísti ei, allelúja."}],"Secreta":[{"k":"text","la":"Múnera, Dómine, tibi dicáta sanctífica: et, intercedénte beáto Saturníno Mártyre tuo, per hæc eádem nos placátus inténde."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Joann 12:26"},{"k":"text","la":"Qui mihi mínistrat, me sequátur: et ubi sum ego, illic et miníster meus erit. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Sanctíficet nos, quǽsumus, Dómine, tui percéptio sacraménti: et intercessióne Sanctórum tuórum tibi reddat accéptos."},{"k":"macro","name":"Per Dominum"}]},"hr":{"eff377331cd1564a":{"t":"<i>Pomolimo se</i>.\nBože, koji nam daješ da se veselimo rođendanu blaženoga Saturnina mučenika tvoga, udijeli nam i pomoć po njegovim zaslugama.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"5828774eddf3256f":{"t":"Posveti, Gospodine, darove tebi prikazane i po zagovoru blaženoga Saturnina mučenika tvoga njima ublažen pogledaj na nas.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"e9ae3e0c5c49684e":{"t":"<i>Pomolimo se</i>.\nPosvetilo nas, molimo, Gospodine, primanje tvoga otajstva i učinilo nas po zagovoru tvojih svetih tebi milima.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
